import json
import pytz
from datetime import datetime
from taf.analyzer.base.log_entry import LogEntry


class JournalEntry(LogEntry):
    """
    JournalEntry provides below functionalities:

    - binds timestamp and it's corresponding json_entry together to provide JournalEntry object

    - Represents JournalEntry object into readable format.

    - Methods to access json_entry and key values.

    Methods:

    - :meth:`parse`: Combine json_entry and it's timestamp together and return JournalEntry

    Attributes:
    - :attr:`timezone`: timezone offset
    - :attr:`json_entry`: Journal entry

    """

    def __init__(self, json_entry, **kwargs):
        """
        Create a JournalEntry from json_entry

        :param str json_entry: json_entry as input

        """
        super(JournalEntry, self).__init__(**kwargs)
        try:
            self.__json_entry = {k.strip("_").lower(): v for k, v in json.loads(json_entry).items()}
        except Exception:
            raise SyntaxError("Improper json syntax:{entry}".format(entry=json_entry))

    def __str__(self):
        """
        Converts JournalEntry into pretty readable string format.

        :return: string representation of JournalEntry
        :rtype: str

        """
        return json.dumps(
            dict(timestamp=str(self.timestamp), journal_entry=self.__json_entry),
            indent=4,
            sort_keys=True
        )

    @property
    def json_entry(self):
        """
        Provide json_entry of JournalEntry

        :return: Returns a json_entry
        :rtype: dict

        """
        return self.__json_entry

    @classmethod
    def parse(cls, timezone, json_entry):
        """
        Combine json_entry and it's timestamp together and return JournalEntry

        :param str json_entry: json_entry as input.
        :param str timezone: timezone offset

        :return: returns a JournalEntry
        :rtype: JournalEntry

        """
        aware_timestamp = pytz.timezone(timezone).localize(datetime.utcfromtimestamp(
            float(json.loads(json_entry)["__REALTIME_TIMESTAMP"]) / 1000000))
        return JournalEntry(
            timestamp=aware_timestamp,
            json_entry=json_entry)

    def __getattr__(self, key):
        """
        Provide value of a key from json entry.

        This can be access like this-

        Eg: - journal_entry_obj.message
            - journal_entry_obj.realtime_timestamp

        :param key: key of json entry

        :return: value of key

        """
        return self.__json_entry.get(key)

    def __eq__(self, other):
        """Compares two JournalEntry object

        :param other: Another JournalEntry object

        :return: returns true if attribute values of two instances are same
        """
        if self is other:
            return True
        elif not isinstance(other, JournalEntry):
            return False
        else:
            return super(JournalEntry, self).__eq__(other) and self.__json_entry == other.__json_entry
